export function rangesFor(q: string, brand: string, mt: string): M[] {
  const qOk = q.trim().split(/\s+/).some((w: string) => w.length >= 3);
  return qOk ? mFilter(q, brand, "all", true, mt) : (brand !== "all" || mt !== "all") ? mFilter("", brand, "all", false, mt) : [];
}

export function tablesFor(brand: string, mt: string): Record<string, boolean> {
  const s: Record<string, boolean> = {};
  if (mt === "all") return s;
  mFilter("", brand, "all", false, mt).forEach((m: M) => { if (m[7]) s[m[0] + "|" + m[7]] = true; });
  return s;
}

export function codesFor(q: string, brand: string, cat: string, ser: string, mt: string, tset: Record<string, boolean>): Item[] {
  const n = nz(q.trim());
  return ALL.filter((e: Item) => {
    if (brand === "all" && (e.b === "mu" && e.s.indexOf("H3") >= 0 || e.b === "ai")) return false;
    if (brand !== "all" && e.b !== brand) return false;
    if (cat !== "all" && e.k !== cat) return false;
    if (ser && e.s !== ser) return false;
    if (mt !== "all" && !tset[e.b + "|" + e.s]) return false;
    if (!n) return true;
    const hay = nz(e.c + " " + e.m + " " + e.s + " " + BL[e.b] + " " + e.x.join(" ") + (MAL[e.b + "|" + e.s] || ""));
    return hit(hay, n);
  });
}
